// apps/api/src/llms/llm.service.ts
@Injectable()
export class LLMService {
  constructor(
    private readonly centralizedRoutingService: CentralizedRoutingService,
    private readonly runMetadataService: RunMetadataService,
    private readonly providerConfigService: ProviderConfigService,
    private readonly secretRedactionService: SecretRedactionService,
    private readonly localModelStatusService: LocalModelStatusService,
  ) {}

  async generateResponse(prompt: string, options: any = {}): Promise<{
    response: string;
    runMetadata: {
      runId: string;
      provider: string;
      model: string;
      tier: 'local' | 'centralized' | 'external';
      cost: number;
      duration: number;
    }
  }> {
    // Get routing decision from centralized routing service
    const routingDecision = await this.centralizedRoutingService.determineRoute(prompt, options);

    // Start tracking metadata
    const metadataContext = this.runMetadataService.startRequest(routingDecision);

    try {
      // Get provider configuration
      const providerConfig = this.providerConfigService.getConfig(routingDecision.provider);

      // Add required headers
      const headers = this.getDefaultHeaders(options, providerConfig);

      // Call provider with appropriate configuration
      const response = await this.callProvider(routingDecision, prompt, headers, options);

      // Complete metadata tracking
      const runMetadata = this.runMetadataService.completeRequest(metadataContext, response);

      return {
        response: response.content,
        runMetadata
      };
    } catch (error) {
      // Handle errors and still return metadata
      const runMetadata = this.runMetadataService.completeRequestWithError(metadataContext, error);
      throw new Error(`LLM request failed: ${error.message}`);
    }
  }

  private getDefaultHeaders(options: any, providerConfig: any) {
    return {
      'X-Policy-Profile': options.policyProfile || 'standard',
      'X-Data-Class': options.dataClass || 'public',
      'X-Sovereign-Mode': options.sovereignMode || 'false',
      ...providerConfig.headers
    };
  }

  private async callProvider(routingDecision: any, prompt: string, headers: any, options: any) {
